parameters.jsCode:
const run = $input.first().json;
const steps = run.intermediateSteps || [];

const clean = (text) => {
  if (!text) return '';
  if (typeof text === 'object') text = text.output || text.response || text.text || JSON.stringify(text);
  return String(text).trim();
};

const resultOf = (keys) => {
  const step = steps.find(s => {
    const toolName = String(s.action?.tool || '').toLowerCase();
    return keys.some(k => toolName.includes(k));
  });
  return step ? clean(step.observation) : null;
};

const sections = [
  ['📊 Match Analysis', resultOf(['matcher', 'cv']), 'CV Matcher'],
  ['✉️ Tailored Cover Letter', resultOf(['letter', 'cover']), 'Cover Letter Writer'],
  ['🎯 Interview Preparation', resultOf(['interview', 'coach', 'question']), 'Interview Coach'],
];

const report = [run.output]
  .concat(sections.map(([title, body, agent]) => '## ' + title + '\n\n' + (body || '_The ' + agent + ' did not run this time. Please submit the form again._')))
  .join('\n\n---\n\n');

return [{ json: { report, specialistsUsed: sections.filter(s => s[1]).length } }];

